def sequence(n):
    if n == 1:
        return 10

    a_n_minus_1 = sequence(n-1)
    n_minus_1 = n - 1

    # a_{n+1} = 6a_n - 2^{n+2} - 3^{n+1} + 5
    # Here, n is the index we want, so we use the formula for a_n
    # a_n = 6*a_{n-1} - 2^{n+1} - 3^{n} + 5
    return 6 * a_n_minus_1 - (2**(n+1)) - (3**n) + 5

# Calculate the first few terms and their residues mod 2, 3, 5
